value.string:
{
 "additionalProperties": true, 
 "type": "object", 
 "description": "Catalog search results, or the total count when count_only was asked for.", 
 "properties": {
 "count": {
 "type": "integer"
 }, 
 "total_count": {
 "type": [
 "integer", 
 "null"
 ], 
 "description": "Total number of matching documents; present only with count_only. Exact, not a heuristic."
 }, 
 "has_more": {
 "type": "boolean"
 }, 
 "offset": {
 "type": "integer"
 }, 
 "results": {
 "items": {
 "type": "object"
 }, 
 "type": "array"
 }, 
 "next_offset": {
 "type": [
 "integer", 
 "null"
 ]
 }, 
 "error": {
 "type": "string", 
 "description": "Error message; present only on failure."
 }, 
 "filters_applied": {
 "type": "object", 
 "description": "The column criteria parsed out of 'query' and actually sent to the catalog, with two bounds on one column combined into a single range criterion. Check it when a result surprises you: it says what was really asked."
 }, 
 "warning": {
 "type": "string", 
 "description": "A criterion was NOT applied - the query used OR/NOT/parentheses, or one column got a combination that cannot be expressed as a single criterion. Read this before trusting the rows: in that respect the result is unfiltered, not empty."
 }, 
 "hint": {
 "type": "string", 
 "description": "This search hit a limit of the plain catalog path and the answer may be incomplete or unfiltered - typically a listbox column that only the module's own list_method can resolve. Read it before trusting the rows, and follow it: it names the tool to use instead, usually erp5_collect."
 }
 }
 }

{
 "additionalProperties": false, 
 "required": [], 
 "type": "object", 
 "properties": {
 "relative_url": {
 "default": null, 
 "type": [
 "string", 
 "null"
 ], 
 "description": "Module id or document path to search inside. Omit it to search the WHOLE PORTAL across modules - the same catalog the UI's global search field queries. Scoping to a module is that same catalog restricted to the module's contents, so a portal-wide search returns a superset."
 }, 
 "sort_on": {
 "default": null, 
 "type": [
 "array", 
 "null"
 ], 
 "description": "Sort order as a [column, direction] pair, e.g. [\"modification_date\", \"descending\"]. For multi-key sort pass a list of such pairs, e.g. [[\"modification_date\", \"descending\"], [\"title\", \"ascending\"]]. direction is \"ascending\" or \"descending\" (defaults to \"ascending\" if omitted)."
 }, 
 "select_list": {
 "default": [], 
 "type": "array", 
 "description": "Columns to return."
 }, 
 "limit": {
 "default": 50, 
 "type": "integer", 
 "description": "Max rows."
 }, 
 "offset": {
 "default": 0, 
 "type": "integer", 
 "description": "Pagination offset."
 }, 
 "count_only": {
 "default": false, 
 "type": [
 "boolean", 
 "integer", 
 "string", 
 "null"
 ], 
 "description": "Return only the total number of matching documents, as 'total_count', in a single catalog COUNT query -- no rows, no pagination. Use this instead of paging through every result just to count them. Works portal-wide too."
 }, 
 "query": {
 "default": null, 
 "type": [
 "string", 
 "null"
 ], 
 "description": "Catalog criteria. 'column:value' or 'column:\"value with spaces\"' becomes a criterion on that column; terms are ANDed, and a literal AND between them is optional. Naming the SAME column twice is an OR on its values, e.g. 'portal_type:\"Sale Order\" portal_type:\"Organisation\"'. Comparisons are understood - 'modification_date:>=2024-06-01 AND modification_date:<2024-07-01' becomes one range criterion, quoted or not. OR, NOT and parentheses cannot be mapped: the whole query is then dropped and 'warning' says so. Words with no column are matched as title LIKE %words%, and only when no column term is present. What was really sent is echoed back in 'filters_applied'."
 }
 }
 }
